sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = ["entitlement.dashboard"]; // Updated sys_property name
    var kpiValues = {
        'kpi_data': []
    };

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName); // Fetch system property

        if (propertyValue) {
            try {
                gs.info("Raw property value for " + propertyName + ": " + propertyValue);
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.info("Error parsing " + propertyName + ": " + e.message);
            }
        } else {
            gs.info("Property " + propertyName + " is not set or is empty.");
        }
        return kpis;
    }

    function processKPI(kpis) {
        if (Array.isArray(kpis.output)) {
            kpis.output.forEach(function (kpi) {
                kpiValues.kpi_data.push({
                    "name": kpi.kpi || "Unknown KPI",
                    "count": kpi.count || 0
                });
            });
            gs.info("Processed KPI values: " + JSON.stringify(kpiValues.kpi_data));
        } else {
            gs.info("Invalid KPI format: Expected an array but got " + typeof kpis.output);
        }
    }

    kpiProperties.forEach(function (property) {
        var kpiData = fetchKPIs(property);
        processKPI(kpiData);
    });

    kpiValues['kpi_data'] = [
        {
            "data": kpiValues.kpi_data.map(kpi => ({
                "entitlement_metric": kpi.name, // Updated key to match entitlement metrics
                "value": kpi.count
            })),
            "metadata": {
                "dataSourceLabel": "Entitlement",
                "eventData": {
                    "table": "samp_entitlement", // Updated to Entitlement-related table
                    "query": "active=true" // Query for active entitlements
                },
                "groupBy": [
                    {
                        "series": [
                            {
                                "id": "value",
                                "type": "value",
                                "label": "Entitlement KPIs"
                            }
                        ],
                        "elements": [
                            {
                                "eventData": {
                                    "query": "active=true"
                                },
                                "id": "active_entitlement",
                                "label": "Active Entitlements"
                            }
                        ],
                        "id": "entitlement_metric",
                        "fieldType": "reference",
                        "label": "Entitlement Metrics"
                    }
                ],
                "format": {
                    "unitFormat": "{0}"
                },
                "aggregateBy": 4,
                "metricId": "ZW50aXRsZW1lbnQubWV0cmljcy5pZD1FTlRJVExFTUVOVF9NRVRSSUNT"
            }
        }
    ];

    return kpiValues;
}
